{
  "date": "2026-09-12",
  "scope": "Top-level wave/nonhydrostatic dispatch and selected manual semantics; not every numerical option or complete routine reachability",
  "human_approval_issued": false,
  "modes": [
    {
      "id": "stationary",
      "guard": "swave==1 and wavemodel==STATIONARY",
      "sequence": [
        "wave",
        "wave_dispersion(0)",
        "wave_stationary_directions(0)"
      ],
      "update_guard": "abs(mod(t,wavint)) < 0.001*dt or newstatbc==1"
    },
    {
      "id": "surfbeat_directional",
      "guard": "swave==1 and wavemodel==SURFBEAT and single_dir!=1",
      "sequence": [
        "wave",
        "optional update_means_wave_flow if wci==1",
        "wave_dispersion(2 if wci==1 else 0)",
        "wave_instationary"
      ],
      "update_guard": "each successful physics step"
    },
    {
      "id": "surfbeat_single_dir",
      "guard": "swave==1 and wavemodel==SURFBEAT and single_dir==1",
      "sequence": [
        "wave",
        "update_means_wave_flow",
        "conditional wave_dispersion(1), wave_stationary_directions(1)",
        "wave_dispersion(2 if wci==1 else 0)",
        "wave_instationary"
      ],
      "update_guard": "direction solve at abs(mod(t,wavint)) < 0.001*dt or newstatbc==1 or t==dt; wave_instationary each successful physics step"
    },
    {
      "id": "nonh_one_layer",
      "guard": "wavemodel==NONH and nonhq3d!=1",
      "sequence": [
        "flow",
        "nonh_cor(0) -> nonh_1lay_pred",
        "flow_secondorder_advUV",
        "nonh_cor(1) -> nonh_1lay_cor"
      ],
      "update_guard": "each successful physics step; input validation turns secorder on"
    },
    {
      "id": "nonh_two_layer_2dv",
      "guard": "wavemodel==NONH and nonhq3d==1 and s%ny==0",
      "sequence": [
        "flow",
        "nonh_cor(0) -> nonh_2lay_pred_2dV",
        "flow_secondorder_advUV",
        "nonh_cor(1) -> nonh_2lay_cor_2dV"
      ],
      "update_guard": "each successful physics step; local s%ny selects the branch"
    },
    {
      "id": "nonh_two_layer_3d",
      "guard": "wavemodel==NONH and nonhq3d==1 and s%ny!=0",
      "sequence": [
        "flow",
        "nonh_cor(0) -> nonh_2lay_pred_3d",
        "flow_secondorder_advUV",
        "nonh_cor(1) -> nonh_2lay_cor_3d"
      ],
      "update_guard": "each successful physics step; local s%ny selects the branch"
    }
  ],
