      "line_end": 658,
      "sha256": "50742b601cc8feccd513cf742ca772b6021f1d4f5ffe074c4e8ffc90907dd2b2",
      "quote_exact_utf8": "#ifdef USEMPI\r\n      call xmpi_shift_ee(s%uu)\r\n      call xmpi_shift_ee(s%vv)\r\n#endif\r\n\r\n      if (par%wavemodel==WAVEMODEL_NONH) then\r\n         !Do explicit predictor step with pressure\r\n         call nonh_cor(s,par,0,uu_old,vv_old)\r\n\r\n#ifdef USEMPI\r\n         call xmpi_shift_ee(s%uu)\r\n         call xmpi_shift_ee(s%vv)\r\n#endif\r\n      end if\r\n\r\n      if (par%secorder==1) then\r\n         !Call second order correction to the advection\r\n         call flow_secondorder_advUV(s,par,uu_old,vv_old)\r\n#ifdef USEMPI\r\n         call xmpi_shift_ee(s%uu)\r\n         call xmpi_shift_ee(s%vv)\r\n#endif\r\n      end if\r\n\r\n      if (par%wavemodel==WAVEMODEL_NONH) then\r\n         ! do non-hydrostatic pressure compensation to solve short waves\r\n         call nonh_cor(s,par,1,uu_old,vv_old)\r\n         ! note: MPI shift in subroutine nonh_cor\r\n      end if\r"
    },
    {
      "path": "models/XBeach/raw/source_code/trunk/src/xbeachlibrary/nonh.F90",
      "line_start": 201,
      "line_end": 249,
      "sha256": "18f471b386e5905a78c98c24fc2f6252ae4fc66c9e2010665e5f35a59d324583",
      "quote_exact_utf8": "      select case ( par%nonhq3d )\r\n         !\r\n       case (1)\r\n         !\r\n         ! The \"new\" reduced two-layer formulations are used\r\n         !\r\n         if ( ipredcor == 0 ) then\r\n            ! -- Predictor\r\n            if ( s%ny == 0 ) then\r\n               ! -- 2dv code path\r\n               call nonh_2lay_pred_2dV(s,par,uu0)\r\n               !\r\n            else\r\n               ! -- \"3d\" code path\r\n               call nonh_2lay_pred_3d(s,par,uu0,vv0)\r\n               !\r\n            endif\r\n            !\r\n         else\r\n            !\r\n            if ( s%ny == 0 ) then\r\n               !\r\n               call nonh_2lay_cor_2dV(s,par)\r\n               !\r\n            else\r\n               !\r\n               call nonh_2lay_cor_3d(s,par)\r\n               !\r\n            endif\r\n            !\r\n         endif\r\n         !\r\n       case default\r\n         !\r\n         ! The \"old\" code is used\r\n         !\r\n         if ( ipredcor == 0 ) then\r\n            ! -- Predictor\r\n            call nonh_1lay_pred(s,par)\r\n            !\r\n         else\r\n            ! -- Corrector\r\n            call nonh_1lay_cor(s,par)\r\n            !\r\n         endif\r\n         !\r\n      end select\r\n      !\r\n   end subroutine nonh_cor\r"
    },
    {
